const get=async(url)=>{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),15000);try{const r=await fetch(url,{redirect:'follow',signal:ctrl.signal,headers:{'User-Agent':'4PLANET-Public-SEO-Audit/1.0'}});return{status:r.status,url:r.url,headers:r.headers,body:(await r.text()).slice(0,1800000)}}catch(e){return{status:0,url,headers:new Headers(),body:'',error:String(e.name||e)}}finally{clearTimeout(timer)}};
const first=(s,r)=>(s.match(r)||[])[1]||'';
const clean=s=>String(s||'').replace(/<[^>]+>/g,' ').replace(/&(?:amp|nbsp|quot);/g,' ').replace(/\s+/g,' ').trim();
function check(r,url,fromSitemap){const h=r.body;const tag=[...h.matchAll(/<meta\b[^>]*>/gi)].map(x=>x[0]);const meta=n=>{const t=tag.find(x=>x.includes('name="'+n+'"')||x.includes("name='"+n+"'"));return t?first(t,/\bcontent=["']([^"']*)/i):''};const link=[...h.matchAll(/<link\b[^>]*>/gi)].map(x=>x[0]).find(x=>/rel=["']canonical["']/i.test(x))||'';const canonical=first(link,/\bhref=["']([^"']*)/i);const robots=meta('robots')||meta('googlebot'),xRobots=r.headers.get('x-robots-tag')||'';const index=/\bnoindex\b/i.test(robots+' '+xRobots)?'NOINDEX':r.status!==200?'NOT_200':canonical&&canonical!==url&&canonical!==r.url?'CANONICAL_OTHER':'ELIGIBLE';const visible=clean(h.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' '));return{url,status:r.status,final:r.url,host:new URL(url).host,fromSitemap,title:clean(first(h,/<title[^>]*>([\s\S]*?)<\/title>/i)).slice(0,130),h1:clean(first(h,/<h1[^>]*>([\s\S]*?)<\/h1>/i)).slice(0,100),description:meta('description').slice(0,130),robots,xRobots,canonical,index,structured:/<script[^>]*type=["']application\/ld\+json/i.test(h),bodyChars:visible.length,error:r.error||null}}
const sites=[],queued=new Map();for(const host of origins){const base='https://'+host;const robots=await get(base+'/robots.txt');const main=await get(base+'/sitemap.xml');const smap=new Set([base+'/sitemap.xml']);for(const m of robots.body.matchAll(/^sitemap:\s*(https?:\/\/\S+)/gim))smap.add(m[1]);const locs=new Set(),visited=new Set(),q=[...smap];while(q.length&&visited.size<15){const uri=q.shift();if(visited.has(uri))continue;visited.add(uri);const r=uri===base+'/sitemap.xml'?main:await get(uri);if(r.status!==200)continue;for(const m of r.body.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/gi)){try{const url=new URL(m[1].replace(/&amp;/g,'&').trim());if(url.host!==host)continue;const target=url.origin+url.pathname+url.search;if(url.pathname.endsWith('.xml')&&/sitemap/i.test(url.pathname)){if(!visited.has(target))q.push(target)}else locs.add(target)}catch{}}}sites.push({host,robotsStatus:robots.status,robotsText:robots.body.slice(0,650),sitemapStatus:main.status,sitemapUrls:locs.size,referencedSitemaps:[...visited]});for(const u of locs)queued.set(u,true);for(const p of extras[host]||[]){const url=base+p;if(!queued.has(url))queued.set(url,false)}}
const tasks=[...queued],results=new Array(tasks.length);let cursor=0;await Promise.all(Array.from({length:12},async()=>{while(cursor<tasks.length){const i=cursor++;const[url,fromSitemap]=tasks[i];results[i]=check(await get(url),url,fromSitemap)}}));fs.mkdirSync('artifacts',{recursive:true});fs.writeFileSync('artifacts/max-exposure-public-urls-20261019.json',JSON.stringify({date:new Date().toISOString(),sites,pages:results},null,2));for(const site of sites){const pages=results.filter(x=>x.host===site.host),sitemap=pages.filter(x=>x.fromSitemap);const counters=x=>Object.fromEntries(['ELIGIBLE','NOINDEX','NOT_200','CANONICAL_OTHER'].map(k=>[k,x.filter(p=>p.index===k).length]));console.log('SITE '+JSON.stringify({host:site.host,robots:site.robotsStatus,sitemap:site.sitemapStatus,sitemapUrls:site.sitemapUrls,checked:pages.length,sitemapResults:counters(sitemap),allResults:counters(pages),declared:site.referencedSitemaps}));const issues=pages.filter(p=>p.status!==200||p.index!=='ELIGIBLE'||!p.h1||!p.canonical||p.bodyChars<250||!p.structured);for(const p of issues.slice(0,site.host==='4planetatlas.com'?20:65))console.log('ISSUE '+JSON.stringify({url:p.url,status:p.status,index:p.index,canonical:p.canonical,robots:p.robots,h1:p.h1,structured:p.structured,bodyChars:p.bodyChars,final:p.final,error:p.error}));if(['4planet.org','4planetmagazine.com','4species.com','4sapien.com','s4piens.com','4brands.org','4nation.org'].includes(site.host)){let selected=pages.filter(p=>site.host==='4planet.org'?p.url.includes('/missions/'):site.host==='4planetmagazine.com'?p.fromSitemap:!p.fromSitemap);for(const p of selected.slice(0,site.host==='4planetmagazine.com'?115:45))console.log('CONTENT '+JSON.stringify({url:p.url,status:p.status,index:p.index,canonical:p.canonical,robots:p.robots,h1:p.h1,bodyChars:p.bodyChars,structured:p.structured}))}}console.log('AUDIT_DONE '+JSON.stringify({pages:results.length,domains:sites.length}));
